  pillarsHeading: { en: "Engineered for India's Public Healthcare Reality", hi: "भारत की ग्रामीण सार्वजनिक स्वास्थ्य आवश्यकताओं के अनुरूप निर्मित", te: "భారతీయ ప్రజా ఆరోగ్య అవసరాలకు అనుగుణంగా రూపొందించబడింది" },
  pillar1Title: { en: "Voice-First Accessibility", hi: "आवाज-प्रथम पहुंच (Voice AI)", te: "వాయిస్-ఫస్ట్ యాక్సెసిబిలిటీ (Voice AI)" },
  pillar1Desc: { en: "Overcomes rural literacy barriers through native speech recognition in regional Indian languages with automatic speech synthesis read-aloud.", hi: "क्षेत्रीय भारतीय भाषाओं में आवाज पहचान के माध्यम से ग्रामीण निरक्षरता की बाधा को दूर करता है।", te: "ప్రాంతీయ భారతీయ భాషలలో వాయిస్ రికగ్నిషన్ ద్వారా గ్రామీణ నిరక్షరాస్యత అడ్డంకులను అధిగమిస్తుంది." },
  pillar2Title: { en: "Offline-First IndexedDB", hi: "ऑफ़लाइन-प्रथम IndexedDB", te: "ఆఫ్‌లైన్-ఫస్ట్ IndexedDB" },
  pillar2Desc: { en: "Functions seamlessly in remote forest and rural tribal belts with zero mobile connectivity. Background synchronization pushes records when network returns.", hi: "इंटरनेट रहित सुदूर जंगलों और आदिवासी क्षेत्रों में भी बिना रुकावट काम करता है। नेटवर्क मिलने पर स्वतः सिंक होता है।", te: "ఇంటర్నెట్ లేని మారుమూల అటవీ మరియు గిరిజన ప్రాంతాల్లో కూడా నిరంతరాయంగా పనిచేస్తుంది." },
  pillar3Title: { en: "Grounded Clinical AI", hi: "क्लिनिकल एआई सहायक", te: "క్లినికల్ AI అసిస్టెంట్" },
  pillar3Desc: { en: "Human-in-the-loop medical AI summarizes complex longitudinal vitals and symptoms into structured SOAP notes without replacing licensed clinical judgment.", hi: "डॉक्टर के निर्णय में सहायता हेतु जटिल स्वास्थ्य डेटा को संरचित SOAP नोट्स में बदलता है।", te: "వైద్యుల నిర్ణయాలకు సహాయంగా సంక్లిష్ట ఆరోగ్య డేటాను నిర్మాణాత్మక SOAP నోట్స్‌గా మారుస్తుంది." },
  pillar4Title: { en: "ABDM & ABHA Integration", hi: "ABDM और आभा (ABHA) जुड़ाव", te: "ABDM మరియు ఆభా (ABHA) లింకేజ్" },
  pillar4Desc: { en: "Standardized 14-digit ABHA citizen identifier linkage with patient-controlled consent revocation for complete data sovereignty.", hi: "14-अंकीय आभा पहचान संख्या और मरीज़-नियंत्रित डेटा सहमति प्रबंधन।", te: "14-అంకెల ఆభా గుర్తింపు సంఖ్య మరియు రోగి-నియంత్రిత డేటా గోప్యతా నిర్వహణ." },
  pillar5Title: { en: "108 Emergency Telemetry", hi: "108 आपातकालीन टेलीमेट्री", te: "108 అత్యవసర టెలిమెట్రీ" },
  pillar5Desc: { en: "One-tap SOS broadcasts live GPS coordinates and critical allergy flags directly to emergency response ambulances and PHC dispatchers.", hi: "एक टैप से लाइव जीपीएस और एलर्जी संबंधी जानकारी सीधे 108 एम्बुलेंस और अस्पताल को प्रेषित।", te: "ఒకే ట్యాప్‌తో లైవ్ GPS మరియు అలర్జీ వివరాలు నేరుగా 108 అంబులెన్స్‌కు చేరుతాయి." },
  pillar6Title: { en: "Paper Record OCR Scan", hi: "कागज़ी पर्ची ओसीआर स्कैन", te: "పాత కాగితపు రికార్డుల OCR స్కాన్" },
  pillar6Desc: { en: "Transforms physical prescription slips and legacy hospital discharge cards into structured, queryable electronic health records.", hi: "पुरानी कागज़ी पर्चियों और अस्पताल कार्ड को डिजिटल स्वास्थ्य रिकॉर्ड में बदलता है।", te: "పాత కాగితపు ప్రిస్క్రిప్షన్‌లను డిజిటల్ ఆరోగ్య రికార్డులుగా మారుస్తుంది." },
  juryTourHeading: { en: "SIH Evaluator & Jury Quick-Start Tour", hi: "मूल्यांकनकर्ता एवं जूरी के लिए त्वरित टूर", te: "మూల్యాంకనం & జ్యూరీ కోసం త్వరిత గైడ్" },
  juryTourDesc: { en: "To test the complete cross-role feedback loop: Log a symptom in the Patient Voice Assistant → Observe priority queue elevation in the Doctor Workspace → Sign an e-prescription → Record household vitals in the ASHA Workspace → Sync offline queue.", hi: "संपूर्ण क्रॉस-रोल प्रवाह का परीक्षण करने के लिए: मरीज़ वॉयस असिस्टेंट में लक्षण बोलें → डॉक्टर वर्कस्पेस में कतार देखें → ई-पर्चा जारी करें → आशा वर्कस्पेस में वाइटल्स दर्ज करें → ऑफ़लाइन सिंक करें।", te: "మొత్తం ప్రక్రియను పరీక్షించడానికి: రోగుల వాయిస్ అసిస్టెంట్‌లో మాట్లాడండి → డాక్టర్ వద్ద క్యూ చూడండి → e-ప్రిస్క్రిప్షన్ ఇవ్వండి → ఆశా వర్క్‌స్పేస్‌లో వైటల్స్ నమోదు చేయండి → ఆఫ్‌లైన్ సింక్ చేయండి." },
