  vitalRefSugar: { en: "<strong>Random Sugar:</strong> Normal (&lt; 140 mg/dL) • <span style=\"color:var(--status-high); font-weight:700;\">High (&gt; 160 mg/dL)</span>", hi: "<strong>रैंडम शुगर:</strong> सामान्य (&lt; 140 mg/dL) • <span style=\"color:var(--status-high); font-weight:700;\">अधिक (&gt; 160 mg/dL)</span>", te: "<strong>రాండమ్ షుగర్:</strong> సాధారణం (&lt; 140 mg/dL) • <span style=\"color:var(--status-high); font-weight:700;\">ఎక్కువ (&gt; 160 mg/dL)</span>" },
