  workVoiceSample1: { en: "\"రక్తపోటు ఎక్కువగా ఉంది\" (Telugu)", hi: "\"రక్తపోటు ఎక్కువగా ఉంది\" (Telugu)", te: "\"రక్తపోటు ఎక్కువగా ఉంది\" (Telugu)" },
