  workVoiceTryAgain: { en: "Try Again", hi: "फिर से प्रयास करें", te: "మళ్లీ ప్రయత్నించండి" },
  workVoiceSaveBtn: { en: "Save to Patient Record", hi: "मरीज़ रिकॉर्ड में सहेजें", te: "రోగి రికార్డులో సేవ్ చేయండి" },
  syncSubtitle: { en: "Manage records collected in zero-connectivity rural zones and sync them seamlessly to the central PHC server.", hi: "बिना नेटवर्क वाले ग्रामीण क्षेत्रों में एकत्रित रिकॉर्ड प्रबंधित करें और केंद्रीय PHC सर्वर पर सिंक करें।", te: "నెట్‌వర్క్ లేని గ్రామీణ ప్రాంతాల్లో సేకరించిన రికార్డులను నిర్వహించి కేంద్ర PHC సర్వర్‌కు సింక్ చేయండి." },
