  syncOfflineNotice: { en: "All offline data is preserved safely in your device’s client-side IndexedDB engine.", hi: "सभी ऑफ़लाइन डेटा आपके डिवाइस के क्लाइंट-साइड IndexedDB में सुरक्षित रहता है।", te: "అన్ని ఆఫ్‌లైన్ డేటా మీ డివైస్ క్లయింట్-సైడ్ IndexedDBలో సురక్షితంగా ఉంటుంది." },
  syncOnlineBadge: { en: "Online (PHC Gateway Reachable)", hi: "ऑनलाइन (PHC गेटवे उपलब्ध)", te: "ఆన్‌లైన్ (PHC గేట్‌వే అందుబాటులో ఉంది)" },
